// ---------------------------------------------------------------------------
// Node: Derive Idempotency Key (fail-closed)
//
// The X-GitHub-Delivery header is the ONLY accepted key source.
// GitHub reuses the same delivery ID on every retry of the same logical
// event, making it the ideal idempotency key.
//
// If the header is absent the event is quarantined: no ClickUp mutation
// occurs, and a structured log entry is emitted for manual review.
// ---------------------------------------------------------------------------
const headers = $input.first().json.headers ?? {};
const deliveryId =
  headers['x-github-delivery'] ??
  headers['X-GitHub-Delivery'] ??
  null;

if (!deliveryId) {
  console.warn(
    '[idempotency] QUARANTINE X-GitHub-Delivery header absent; event quarantined for manual review'
  );
  return [
    {
      json: {
        ...$input.first().json,
        _idempotencyKey: null,
        _idempotencyDecision: 'quarantine',
      },
    },
  ];
}

console.log(`[idempotency] derived key=${deliveryId}`);
return [{ json: { ...$input.first().json, _idempotencyKey: deliveryId } }];

// ---------------------------------------------------------------------------
// Node: Idempotency Gate — durable file-based atomic store
//
// Uses O_EXCL (exclusive create) via Node fs.openSync with flag 'wx'.
// The kernel guarantees that exactly one concurrent caller succeeds on
// POSIX and NTFS filesystems.  Records are persisted to disk so they
// survive process restarts.
//
// Store directory: $vars.IDEMPOTENCY_STORE_DIR (configure in n8n Variables).
// Default: /data/n8n/idempotency
//
// TTL: records older than 30 days are swept (GitHub redelivery window is
// 72 h, so 30 days is a safe upper bound).
//
// For multi-instance n8n deployments share the same persistent volume
// across all workers so every instance sees the same store directory.
// ---------------------------------------------------------------------------
const key = $input.first().json._idempotencyKey;

if (!key || $input.first().json._idempotencyDecision === 'quarantine') {
  return [{ json: { ...$input.first().json, _idempotencyDecision: 'quarantine' } }];
}

const fs   = require('node:fs');
const path = require('node:path');

const storeDir = ($vars.IDEMPOTENCY_STORE_DIR ?? '/data/n8n/idempotency').trim();
const TTL_MS   = 30 * 24 * 60 * 60 * 1000;

fs.mkdirSync(storeDir, { recursive: true });

// --- TTL sweep (best-effort, never throws) ---
try {
  const cutoff = Date.now() - TTL_MS;
  for (const entry of fs.readdirSync(storeDir)) {
    if (!entry.endsWith('.json')) continue;
    try {
      const fp = path.join(storeDir, entry);
      if (fs.statSync(fp).mtimeMs < cutoff) {
        fs.unlinkSync(fp);
        console.log(`[idempotency] TTL_EXPIRED removed file=${entry}`);
      }
    } catch { /* ignore per-file errors */ }
  }
} catch { /* ignore directory errors */ }

// --- Atomic claim via O_EXCL exclusive create ---
const safeKey  = encodeURIComponent(key).replace(/%/g, '_');
const filePath = path.join(storeDir, `${safeKey}.json`);
const record   = { key, processedAt: new Date().toISOString(), label: 'first' };

try {
  const fd = fs.openSync(filePath, 'wx');  // O_CREAT | O_EXCL
  fs.writeSync(fd, JSON.stringify(record, null, 2));
  fs.closeSync(fd);
  console.log(`[idempotency] FIRST processing key=${key}`);
  return [{ json: { ...$input.first().json, _idempotencyDecision: 'first' } }];
} catch (err) {
  if (err.code !== 'EEXIST') throw err;
  // Another caller already claimed this key
  let priorProcessedAt = 'unknown';
  try {
    const prior = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    priorProcessedAt = prior.processedAt ?? 'unknown';
  } catch { /* best-effort */ }
  console.log(
    `[idempotency] DUPLICATE suppressed key=${key} first_seen=${priorProcessedAt}`
  );
  return [{
    json: {
      ...$input.first().json,
      _idempotencyDecision: 'duplicate',
      _priorProcessedAt: priorProcessedAt,
    },
  }];
}

// ---------------------------------------------------------------------------
// Node: Log Duplicate / Quarantine Suppression
// Emits a structured log entry so suppressed events are fully observable.
// ---------------------------------------------------------------------------
const decision = $input.first().json._idempotencyDecision;
const key      = $input.first().json._idempotencyKey ?? '(none)';
const when     = $input.first().json._priorProcessedAt ?? 'n/a';
console.log(
  `[idempotency] SUPPRESSED decision=${decision} key=${key} original_processing=${when}`
);
return [{ json: { suppressed: true, decision, key, priorProcessedAt: when } }];

// ---------------------------------------------------------------------------
// Node: Build ClickUp Comment
// Constructs the comment body from the GitHub issue/PR event payload.
// ---------------------------------------------------------------------------
const payload = $input.first().json.body ?? $input.first().json;
const issue   = payload.issue ?? payload.pull_request ?? {};
const repo    = payload.repository?.full_name ?? 'unknown';
const action  = payload.action ?? 'unknown';
const actor   = payload.sender?.login ?? 'unknown';
const key     = $input.first().json._idempotencyKey;

const commentText =
  `**GitHub event** \`${action}\` on \`${repo}\` #${issue.number ?? '?'}` +
  `\nActor: ${actor}` +
  `\nURL: ${issue.html_url ?? ''}` +
  `\n\n_idempotency-key: ${key}_`;

return [{ json: { commentText, idempotencyKey: key, issueNumber: issue.number } }];

// ---------------------------------------------------------------------------
// Node: Log First Processing
// Emits a structured log entry for the successful, non-duplicate path.
// ---------------------------------------------------------------------------
const key    = $input.first().json.idempotencyKey;
const taskId = $vars.CLICKUP_TASK_ID;
console.log(
  `[idempotency] FIRST_PROCESSED key=${key} clickup_task=${taskId} ts=${new Date().toISOString()}`
);
return [{ json: { processed: true, key } }];

// ---------------------------------------------------------------------------
// Node: Derive Idempotency Key
//
// Priority order:
//   1. X-GitHub-Delivery header — reused by GitHub on retries of the same
//      logical event, making it the ideal idempotency key.
//   2. Composite fallback from stable payload fields.
// ---------------------------------------------------------------------------
const headers = $input.first().json.headers ?? {};
const payload = $input.first().json.body ?? {};

const deliveryId = headers['x-github-delivery'] ?? headers['X-GitHub-Delivery'];
const action      = payload.action ?? 'unknown';
const repo        = payload.repository?.full_name ?? 'unknown';
const itemNumber  = payload.issue?.number ?? payload.pull_request?.number ?? 0;

const key = deliveryId
  ? deliveryId
  : `fallback:${repo}:${itemNumber}:${action}`;

console.log(`[idempotency] derived key=${key}`);

return [{ json: { ...payload, _idempotencyKey: key, _headers: headers } }];

// ---------------------------------------------------------------------------
// Node: Idempotency Gate (check-and-set against n8n Static Data)
//
// n8n Static Data persists across executions within the same workflow
// instance. For multi-instance deployments, replace this node with an
// HTTP Request to a shared Redis or key-value endpoint.
// ---------------------------------------------------------------------------
const staticData = $getWorkflowStaticData('global');
const processedKeys = staticData.processedKeys ?? {};

const key = $input.first().json._idempotencyKey;

if (processedKeys[key]) {
  const prior = processedKeys[key];
  console.log(
    `[idempotency] DUPLICATE suppressed key=${key} first_seen=${prior.processedAt}`
  );
  return [
    {
      json: {
        ...$input.first().json,
        _idempotencyDecision: 'duplicate',
        _priorProcessedAt: prior.processedAt,
      },
    },
  ];
}

// Persist BEFORE downstream mutation (check-and-set semantics).
processedKeys[key] = { processedAt: new Date().toISOString() };
staticData.processedKeys = processedKeys;

console.log(`[idempotency] FIRST processing key=${key}`);

return [
  {
    json: {
      ...$input.first().json,
      _idempotencyDecision: 'first',
    },
  },
];

// ---------------------------------------------------------------------------
// Node: Log Duplicate Suppression
// Emits a structured log entry so duplicate events are fully observable.
// ---------------------------------------------------------------------------
const key  = $input.first().json._idempotencyKey;
const when = $input.first().json._priorProcessedAt;
console.log(
  `[idempotency] DUPLICATE_SUPPRESSED key=${key} original_processing=${when}`
);
return [{ json: { suppressed: true, key, priorProcessedAt: when } }];

// ---------------------------------------------------------------------------
// Node: Build ClickUp Comment
// Constructs the comment body from the GitHub issue/PR event payload.
// Adjust `listId` / `taskId` mapping to match your ClickUp space.
// ---------------------------------------------------------------------------
const payload = $input.first().json;
const issue   = payload.issue ?? payload.pull_request ?? {};
const repo    = payload.repository?.full_name ?? 'unknown';
const action  = payload.action ?? 'unknown';
const actor   = payload.sender?.login ?? 'unknown';
const key     = payload._idempotencyKey;

const commentText =
  `**GitHub event** \`${action}\` on \`${repo}\` #${issue.number ?? '?'}` +
  `\nActor: ${actor}` +
  `\nURL: ${issue.html_url ?? ''}` +
  `\n\n_idempotency-key: ${key}_`;

return [{ json: { commentText, idempotencyKey: key, issueNumber: issue.number } }];

// ---------------------------------------------------------------------------
// Node: Log First Processing
// Emits a structured log entry for the successful, non-duplicate path.
// ---------------------------------------------------------------------------
const key    = $input.first().json.idempotencyKey;
const taskId = $vars.CLICKUP_TASK_ID;
console.log(
  `[idempotency] FIRST_PROCESSED key=${key} clickup_task=${taskId} ts=${new Date().toISOString()}`
);
return [{ json: { processed: true, key } }];
